#pragma once
#include <string>
#include <vector>

namespace blitz::tidy {
	/** What blitz-tidy does with the findings of a rule. */
	enum class mode { OFF, REPORT, FIX };

	std::string to_string(mode m);
	bool        parse_mode(std::string const& text, mode& out);

	/** A rule is a warning of the compiler, together with what blitz-tidy can do about it. */
	struct rule {
		const char* name;           // The name of the warning, such as "implicit-lossy-real-to-int".
		bool        fixable;        // Whether blitz-tidy knows how to fix it at all.
		mode        default_mode;   // FIX for rules that can be fixed without changing the program, REPORT for the rest.
		const char* fix;            // What the fix does.
		const char* unsafe;         // When the fix changes the program (needs "unsafe"), empty if it never does.
	};

	std::vector<rule> const& all_rules();
	rule const*              find_rule(std::string const& name);
} // namespace blitz::tidy
